    def __init__(self):
        self.devices = {}

    def add_device(self, device, initial_state):
        self.devices[device] = initial_state

    def execute_command(self, command):
        if command.device in self.devices:
            self.devices[command.device] = getattr(self.devices[command.device], command.action)()

    def predict_next_states(self, commands):
